//! Rust code emitter: one module per domain, plus shared enums and unions.

use std::fmt::Write as _;

use crate::schema::{FieldType, Schema, TypeDef};

const DERIVES: &str = "#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]";

/// Render the whole schema as a single Rust source file.
pub fn emit(schema: &Schema) -> String {
    let mut out = String::new();
    let _ = writeln!(
        out,
        "//! Generated by corpora-typegen from schema/model.json v{}.\n\
         //! Do not edit by hand.\n",
        schema.version
    );

    for (name, def) in &schema.enums {
        let _ = writeln!(out, "/// {}", def.description);
        let _ = writeln!(out, "{DERIVES}");
        let _ = writeln!(out, "pub enum {name} {{");
        for value in &def.values {
            let _ = writeln!(out, "    /// `{value}`");
            let _ = writeln!(out, "    #[serde(rename = \"{value}\")]");
            let _ = writeln!(out, "    {},", variant_name(value));
        }
        let _ = writeln!(out, "}}\n");
    }

    for (name, def) in &schema.unions {
        let _ = writeln!(out, "/// {}", def.description);
        let _ = writeln!(out, "{DERIVES}");
        let _ = writeln!(out, "#[serde(tag = \"type\", rename_all = \"snake_case\")]");
        let _ = writeln!(out, "pub enum {name} {{");
        for variant in &def.variants {
            let _ = writeln!(out, "    /// A `{variant}` node.");
            let _ = writeln!(out, "    {variant}({variant}),");
        }
        let _ = writeln!(out, "}}\n");
    }

    for (domain_name, domain) in &schema.domains {
        let _ = writeln!(out, "// ── {domain_name}: {} ──\n", domain.description);
        for (type_name, type_def) in &domain.types {
            emit_struct(&mut out, schema, type_name, type_def);
        }
    }
    out
}

fn emit_struct(out: &mut String, schema: &Schema, name: &str, def: &TypeDef) {
    let _ = writeln!(out, "/// {}", def.description);
    let _ = writeln!(out, "{DERIVES}");
    let _ = writeln!(out, "pub struct {name} {{");
    if let Some(parent) = def.extends.as_deref() {
        if let Some((_, parent_def)) = schema.find_type(parent) {
            emit_fields(out, schema, parent_def);
        }
    }
    emit_fields(out, schema, def);
    let _ = writeln!(out, "}}\n");
}

fn emit_fields(out: &mut String, schema: &Schema, def: &TypeDef) {
    for (field_name, field) in def.fields() {
        let _ = writeln!(out, "    /// {}", field.description);
        let rust_name = escape_keyword(field_name);
        if rust_name != field_name {
            let _ = writeln!(out, "    #[serde(rename = \"{field_name}\")]");
        }
        let ty = rust_type(schema, &FieldType::parse(&field.ty));
        let _ = writeln!(out, "    pub {rust_name}: {ty},");
    }
}

fn rust_type(schema: &Schema, ty: &FieldType) -> String {
    match ty {
        FieldType::Named(name) => schema
            .scalars
            .get(name)
            .map_or_else(|| name.clone(), |scalar| scalar.rust.clone()),
        FieldType::Optional(inner) => format!("Option<{}>", rust_type(schema, inner)),
        FieldType::List(inner) => format!("Vec<{}>", rust_type(schema, inner)),
        FieldType::Map(key, value) => format!(
            "std::collections::BTreeMap<{}, {}>",
            rust_type(schema, key),
            rust_type(schema, value)
        ),
    }
}

/// `ready-for-review` -> `ReadyForReview`, `tf_zip` -> `TfZip`, `not reviewed` -> `NotReviewed`.
fn variant_name(value: &str) -> String {
    value
        .split(['-', '_', ' '])
        .filter(|part| !part.is_empty())
        .map(|part| {
            let mut chars = part.chars();
            chars.next().map_or_else(String::new, |first| {
                first.to_uppercase().collect::<String>() + chars.as_str()
            })
        })
        .collect()
}

fn escape_keyword(name: &str) -> String {
    match name {
        "type" | "ref" | "use" | "move" | "box" => format!("r#{name}"),
        _ => name.to_owned(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn variant_name_should_pascal_case_kebab_values() {
        assert_eq!(variant_name("ready-for-review"), "ReadyForReview");
    }

    #[test]
    fn variant_name_should_pascal_case_spaced_values() {
        assert_eq!(variant_name("not reviewed"), "NotReviewed");
    }

    #[test]
    fn escape_keyword_should_rawify_type() {
        assert_eq!(escape_keyword("type"), "r#type");
    }
}
